<?php require __DIR__.'/../app/bootstrap.php';require __DIR__.'/_layout.php';$u=require_admin();$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();
    try{
        $tid=(int)($_POST['ticket_id']??0);$act=$_POST['action']??'';
        if($act==='reply'||$act==='note'){
            $body=trim($_POST['message']??'');if($body==='')throw new RuntimeException('Message cannot be empty.');
            $internal=$act==='note'?1:0;
            db()->prepare('INSERT INTO support_messages(ticket_id,user_id,is_staff,is_internal,message) VALUES(?,?,1,?,?)')->execute([$tid,$u['id'],$internal,$body]);
            if(!$internal)db()->prepare("UPDATE support_tickets SET status='awaiting_customer',assigned_admin_id=COALESCE(assigned_admin_id,?),updated_at=NOW() WHERE id=?")->execute([$u['id'],$tid]);
            else db()->prepare('UPDATE support_tickets SET assigned_admin_id=COALESCE(assigned_admin_id,?),updated_at=NOW() WHERE id=?')->execute([$u['id'],$tid]);
            if(!$internal)zoho_crm_try_sync_ticket($tid);
            $msg=$internal?'Internal note added.':'Reply sent.';
        }elseif($act==='update'){
            $status=in_array($_POST['status']??'', ['open','awaiting_customer','awaiting_staff','answered','closed'],true)?$_POST['status']:'open';
            $priority=in_array($_POST['priority']??'', ['low','normal','high','urgent'],true)?$_POST['priority']:'normal';
            $assigned=(int)($_POST['assigned_admin_id']??0)?:null;
            db()->prepare('UPDATE support_tickets SET status=?,priority=?,assigned_admin_id=? WHERE id=?')->execute([$status,$priority,$assigned,$tid]);
            zoho_crm_try_sync_ticket($tid);
            $msg='Ticket updated.';
        }
    }catch(Throwable $e){$err=$e->getMessage();}
}
$id=(int)($_GET['id']??0);$ticket=null;$messages=[];if($id){$q=db()->prepare('SELECT t.*,u.name customer_name,u.email,a.name assigned_name,s.name service_name FROM support_tickets t JOIN users u ON u.id=t.user_id LEFT JOIN users a ON a.id=t.assigned_admin_id LEFT JOIN services s ON s.id=t.service_id WHERE t.id=?');$q->execute([$id]);$ticket=$q->fetch();if($ticket){$q=db()->prepare('SELECT m.*,u.name FROM support_messages m LEFT JOIN users u ON u.id=m.user_id WHERE m.ticket_id=? ORDER BY m.id');$q->execute([$id]);$messages=$q->fetchAll();}}
$status=trim($_GET['status']??'');$sql='SELECT t.*,u.name customer_name,u.email FROM support_tickets t JOIN users u ON u.id=t.user_id';$args=[];if($status!==''){$sql.=' WHERE t.status=?';$args[]=$status;}$sql.=' ORDER BY FIELD(t.priority,"urgent","high","normal","low"),t.updated_at DESC';$q=db()->prepare($sql);$q->execute($args);$tickets=$q->fetchAll();$admins=db()->query("SELECT id,name FROM users WHERE role='admin' AND account_status='active' ORDER BY name")->fetchAll();admin_head($u,'Support Center','support');?><link rel="stylesheet" href="/assets/admin-support.css?v=<?=rawurlencode((string)@filemtime(__DIR__.'/../assets/admin-support.css'))?>"><?php if($msg):?><div class="notice"><?=e($msg)?></div><?php endif?><?php if($err):?><div class="error"><?=e($err)?></div><?php endif?><div class="support-admin-grid"><section class="card"><div class="cardhead"><b>TICKETS</b><span class="muted"><?=count($tickets)?> shown</span></div><div class="ticket-filters"><a class="btn" href="/admin/support.php">All</a><?php foreach(['open','awaiting_staff','awaiting_customer','answered','closed'] as $s):?><a class="btn" href="?status=<?=$s?>"><?=e(ucwords(str_replace('_',' ',$s)))?></a><?php endforeach?></div><div class="ticket-list"><?php foreach($tickets as $t):?><a class="ticket-row <?=$id===$t['id']?'selected':''?>" href="/admin/support.php?id=<?=$t['id']?>"><div><b>#<?=$t['id']?> <?=e($t['subject'])?></b><small><?=e($t['customer_name'])?> · <?=e($t['category'])?> · <?=e($t['priority'])?></small></div><?=admin_badge($t['status'])?></a><?php endforeach?></div></section><?php if($ticket):?><section class="card ticket-thread"><div class="cardhead"><div><b>#<?=$ticket['id']?> <?=e($ticket['subject'])?></b><div class="muted small"><?=e($ticket['customer_name'])?> · <?=e($ticket['email'])?><?=!empty($ticket['service_name'])?' · '.e($ticket['service_name']):''?></div></div><?=admin_badge($ticket['status'])?></div><form method="post" class="admin-form-grid ticket-controls"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="update"><input type="hidden" name="ticket_id" value="<?=$ticket['id']?>"><label>Status<select name="status"><?php foreach(['open','awaiting_customer','awaiting_staff','answered','closed'] as $s):?><option value="<?=$s?>" <?=$ticket['status']===$s?'selected':''?>><?=e(ucwords(str_replace('_',' ',$s)))?></option><?php endforeach?></select></label><label>Priority<select name="priority"><?php foreach(['low','normal','high','urgent'] as $p):?><option value="<?=$p?>" <?=$ticket['priority']===$p?'selected':''?>><?=ucfirst($p)?></option><?php endforeach?></select></label><label>Assigned to<select name="assigned_admin_id"><option value="">Unassigned</option><?php foreach($admins as $a):?><option value="<?=$a['id']?>" <?=$ticket['assigned_admin_id']==$a['id']?'selected':''?>><?=e($a['name'])?></option><?php endforeach?></select></label><button class="btn">Save</button></form><div class="messages"><?php foreach($messages as $m):?><article class="message <?=$m['is_internal']?'internal':($m['is_staff']?'staff':'customer')?>"><div class="message-meta"><b><?=e($m['name']?:'Unknown')?></b><span><?=$m['is_internal']?'INTERNAL NOTE · ':''?><?=e($m['created_at'])?></span></div><div><?=nl2br(e($m['message']))?></div></article><?php endforeach?></div><form method="post" class="ticket-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="ticket_id" value="<?=$ticket['id']?>"><textarea name="message" rows="4" required placeholder="Reply to customer or add an internal note..."></textarea><div class="buttons"><button class="btn primary" name="action" value="reply">Reply to customer</button><button class="btn" name="action" value="note">Add internal note</button><a class="btn" href="/admin/customer.php?id=<?=$ticket['user_id']?>">Customer profile</a></div></form></section><?php endif?></div><?php admin_foot(); ?>
